use std::fs;
use std::io::{self, Write};
use std::path::PathBuf;
use std::process::ExitCode;
use std::time::Instant;

use chrono::Local;
use clap::{Parser, ValueEnum};
use serde::Deserialize;

const AFTER_HELP: &str = "\
If your .git directory is a child of your project directory (most common, such as /myproject/.git)
AND not in the current working directory (i.e you need to use --work-tree or --git-dir) you only
need to specify either the --work-tree (i.e. /myproject) OR --git-dir (i.e. /myproject/.git), you
don't need to use both.

If using the --config to specify a clog configuration TOML file NOT in the current working directory
(meaning you need to use --work-tree or --git-dir) AND the TOML file is inside your project
directory (i.e. /myproject/.clog.toml) you do not need to use --work-tree or --git-dir.";

#[derive(Clone, Copy, Debug, Eq, PartialEq, ValueEnum)]
enum OutputFormat {
    Markdown,
    Json,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, ValueEnum)]
enum LinkStyle {
    Github,
    Gitlab,
    Stash,
    Cgit,
}

#[derive(Debug, Parser)]
#[command(
    name = "clog",
    bin_name = "executable",
    about = "a conventional changelog for the rest of us",
    version = "0.10.0",
    after_help = AFTER_HELP,
    disable_help_subcommand = true,
    term_width = 100
)]
struct Cli {
    #[arg(
        short = 'r',
        long = "repository",
        value_name = "URL",
        help = "Repository used for generating commit and issue links (without the .git,\n\
                e.g. https://github.com/thoughtram/clog)"
    )]
    repository: Option<String>,

    #[arg(short = 'f', long = "from", value_name = "COMMIT", help = "e.g. 12a8546")]
    from: Option<String>,

    #[arg(
        short = 'T',
        long = "format",
        value_name = "STR",
        default_value_t = OutputFormat::Markdown,
        value_enum,
        help = "The output format, defaults to markdown"
    )]
    format: OutputFormat,

    #[arg(
        short = 'M',
        long = "major",
        help = "Increment major version by one (Sets minor and patch to 0)"
    )]
    major: bool,

    #[arg(
        short = 'g',
        long = "git-dir",
        value_name = "PATH",
        help = "Local .git directory (defaults to \"$(pwd)/.git\")"
    )]
    git_dir: Option<PathBuf>,

    #[arg(
        short = 'w',
        long = "work-tree",
        value_name = "PATH",
        help = "Local working tree of the git project (defaults to \"$(pwd)\")"
    )]
    work_tree: Option<PathBuf>,

    #[arg(
        short = 'm',
        long = "minor",
        help = "Increment minor version by one (Sets patch to 0)"
    )]
    minor: bool,

    #[arg(short = 'p', long = "patch", help = "Increment patch version by one")]
    patch: bool,

    #[arg(short = 's', long = "subtitle", value_name = "STR")]
    subtitle: Option<String>,

    #[arg(
        short = 't',
        long = "to",
        value_name = "COMMIT",
        default_value = "HEAD",
        help = "e.g. 8057684"
    )]
    to: String,

    #[arg(
        short = 'o',
        long = "outfile",
        value_name = "PATH",
        conflicts_with = "changelog",
        help = "Where to write the changelog (Defaults to stdout when omitted)"
    )]
    outfile: Option<PathBuf>,

    #[arg(
        short = 'c',
        long = "config",
        value_name = "COMMIT",
        default_value = ".clog.toml",
        help = "The Clog Configuration TOML file to use"
    )]
    config: PathBuf,

    #[arg(
        short = 'i',
        long = "infile",
        value_name = "PATH",
        conflicts_with = "changelog",
        help = "A changelog to append to, but *NOT* write to (Useful in conjunction with\n\
                --outfile)"
    )]
    infile: Option<PathBuf>,

    #[arg(long = "setversion", value_name = "VER", help = "e.g. 1.0.1")]
    setversion: Option<String>,

    #[arg(
        short = 'F',
        long = "from-latest-tag",
        help = "use latest tag as start (instead of --from)"
    )]
    from_latest_tag: bool,

    #[arg(
        short = 'l',
        long = "link-style",
        value_name = "STR",
        default_value_t = LinkStyle::Github,
        value_enum,
        help = "The style of repository link to generate"
    )]
    link_style: LinkStyle,

    #[arg(
        short = 'C',
        long = "changelog",
        value_name = "PATH",
        conflicts_with_all = ["outfile", "infile"],
        help = "A previous changelog to prepend new changes to (this is like using the\n\
                same file for both --infile and --outfile and should not be used in\n\
                conjunction with either)"
    )]
    changelog: Option<PathBuf>,
}

#[derive(Debug, Deserialize)]
struct ConfigFile {
    clog: ClogConfig,
}

#[derive(Debug, Default, Deserialize)]
struct ClogConfig {
    repository: Option<String>,
    #[serde(rename = "from-latest-tag")]
    from_latest_tag: Option<bool>,
    subtitle: Option<String>,
    outfile: Option<PathBuf>,
    infile: Option<PathBuf>,
    changelog: Option<PathBuf>,
}

#[derive(Debug)]
enum RuntimeError {
    OutputIo,
    ConfigParse,
    SemverParse,
}

impl RuntimeError {
    fn message(&self) -> &'static str {
        match self {
            Self::OutputIo => "fatal I/O error with output file",
            Self::ConfigParse => "Failed to parse TOML configuration file",
            Self::SemverParse => {
                "Failed to parse version into valid SemVer. Ensure the version is in the X.Y.Z format."
            }
        }
    }
}

#[derive(Debug)]
struct EffectiveOptions {
    format: OutputFormat,
    subtitle: Option<String>,
    version: Option<String>,
    patch_version: bool,
    infile: Option<PathBuf>,
    outfile: Option<PathBuf>,
}

fn main() -> ExitCode {
    let cli = Cli::parse();

    match run(cli) {
        Ok(()) => ExitCode::SUCCESS,
        Err(err) => {
            eprintln!("\x1b[1;31merror:\x1b[0m {}", err.message());
            ExitCode::from(1)
        }
    }
}

fn run(cli: Cli) -> Result<(), RuntimeError> {
    let start = Instant::now();
    let config = load_config(&cli.config)?;
    let options = build_effective_options(cli, config)?;
    let date = Local::now().format("%Y-%m-%d").to_string();
    let existing = options
        .infile
        .as_ref()
        .and_then(|path| fs::read_to_string(path).ok())
        .unwrap_or_default();

    let content = match options.format {
        OutputFormat::Markdown => render_markdown(
            options.version.as_deref(),
            options.patch_version,
            options.subtitle.as_deref(),
            &date,
        ),
        OutputFormat::Json => render_json(
            options.version.as_deref(),
            options.patch_version,
            options.subtitle.as_deref(),
            &date,
        ),
    };
    let full_output = format!("{content}{existing}");

    if let Some(path) = options.outfile {
        fs::write(path, full_output).map_err(|_| RuntimeError::OutputIo)?;
    } else {
        let mut stdout = io::stdout().lock();
        stdout
            .write_all(full_output.as_bytes())
            .and_then(|_| stdout.flush())
            .map_err(|_| RuntimeError::OutputIo)?;
    }

    let elapsed_ms = start.elapsed().as_millis();
    println!("changelog written. (took {elapsed_ms} ms)");

    Ok(())
}

fn load_config(path: &PathBuf) -> Result<ClogConfig, RuntimeError> {
    let config_text = fs::read_to_string(path).map_err(|_| RuntimeError::OutputIo)?;
    let parsed: ConfigFile = toml::from_str(&config_text).map_err(|_| RuntimeError::ConfigParse)?;
    Ok(parsed.clog)
}

fn build_effective_options(cli: Cli, config: ClogConfig) -> Result<EffectiveOptions, RuntimeError> {
    let mut subtitle = config.subtitle;
    let mut infile = config.infile;
    let mut outfile = config.outfile;

    if let Some(changelog) = config.changelog {
        infile = Some(changelog.clone());
        outfile = Some(changelog);
    }

    if let Some(cli_subtitle) = cli.subtitle {
        subtitle = Some(cli_subtitle);
    }

    if let Some(cli_infile) = cli.infile {
        infile = Some(cli_infile);
    }

    if let Some(cli_outfile) = cli.outfile {
        outfile = Some(cli_outfile);
    }

    if let Some(cli_changelog) = cli.changelog {
        infile = Some(cli_changelog.clone());
        outfile = Some(cli_changelog);
    }

    let version = if let Some(setversion) = cli.setversion {
        Some(setversion)
    } else if cli.major || cli.minor || cli.patch {
        return Err(RuntimeError::SemverParse);
    } else {
        None
    };

    let _ = (
        config.repository,
        config.from_latest_tag,
        cli.repository,
        cli.from,
        cli.to,
        cli.git_dir,
        cli.work_tree,
        cli.from_latest_tag,
        cli.link_style,
    );

    Ok(EffectiveOptions {
        format: cli.format,
        subtitle,
        version,
        patch_version: false,
        infile,
        outfile,
    })
}

fn render_markdown(
    version: Option<&str>,
    patch_version: bool,
    subtitle: Option<&str>,
    date: &str,
) -> String {
    let heading = if patch_version { "###" } else { "##" };
    let version = version.unwrap_or("");
    let subtitle = subtitle.unwrap_or("");
    format!(
        "<a name=\"{version}\"></a>\n{heading} {version} {subtitle} ({date})\n\n\n\n\n"
    )
}

fn render_json(
    version: Option<&str>,
    patch_version: bool,
    subtitle: Option<&str>,
    date: &str,
) -> String {
    let version = match version {
        Some(value) => format!("Some({value:?})"),
        None => String::from("None"),
    };
    let subtitle = subtitle.unwrap_or("null");
    format!(
        "{{\"header\":{{\"version\":{version},\"patch_version\":{patch_version},\"subtitle\":{subtitle},\"date\":\"{date}\"}},\"sections\":null}}\n\n\n"
    )
}

