        generated = _generate_markdown(version_text, subtitle_text, date_text, file_style)
    else:
        version_repr = f"Some({json.dumps(opts.setversion)})" if version_present else "None"
        if not opts.subtitle_provided:
            subtitle_repr = "null"
        else:
            subtitle_repr = opts.subtitle
        generated = _generate_json(version_repr, subtitle_repr, date_text, file_style)

    payload = generated + previous

    if target_path is None:
        _stdout(payload)
    else:
        try:
            with open(target_path, "w", encoding="utf-8") as handle:
                handle.write(payload)
        except OSError:
            return _runtime_error("fatal I/O error with output file")
